mapper.select:
SELECT MEMBER_ID
FROM MEMBER_SOCIAL_ACCOUNT
WHERE PROVIDER = #{provider}
    AND PROVIDER_USER_ID = #{providerUserId}

mapper.update:
UPDATE MEMBER_SOCIAL_ACCOUNT
SET LAST_LOGIN_AT = SYSDATE
WHERE MEMBER_ID = #{memberId}
    AND PROVIDER = #{provider}

mapper.select:
SELECT COUNT(*)
FROM MEMBER_SOCIAL_ACCOUNT
WHERE MEMBER_ID = #{memberId}

mapper.delete:
DELETE FROM MEMBER_SOCIAL_ACCOUNT
WHERE MEMBER_ID = #{memberId}
    AND PROVIDER = #{provider}
